package payments

import (
	"context"
	"log/slog"
)


type Gateway interface{ Capture(ctx context.Context, id string) error }

const maxCaptureAttempts = 3

func Capture(ctx context.Context, gw Gateway, id string) error {
	var err error
	for attempt := 1; attempt <= maxCaptureAttempts; attempt++ {
		if err = gw.Capture(ctx, id); err == nil {
			return nil
		}
		if attempt < maxCaptureAttempts {
			slog.WarnContext(ctx, "capture failed, retrying", "id", id, "attempt", attempt)
		}
	}
	return err
}
